// lon/lat -> SVG x/y for a map object
export function project(map, lon, lat) {
  const [minx, miny, maxx, maxy] = map.bbox;
  const k = map.w / (maxx - minx);
  const cos = Math.cos((((miny + maxy) / 2) * Math.PI) / 180);
  return [(lon - minx) * k, ((maxy - lat) * k) / cos];
}
export const slug = (name) => name.toLowerCase().replace(/[^a-z]+/g, '-');
